public METCrossDockTransferType getTransferType()
{
    METCrossDockTransferType ret = metSalesTable.InternalCrossDockOrder == NoYes::Yes ? METCrossDockTransferType::CrossDock : METCrossDockTransferType::CSD;

    return ret;
}

/// <summary>
/// Retrives door and staging lane id
/// </summary>
/// <returns>container with door and staging lane id</returns>
public container getDoorAndLane()
{
    container ret;
    METStagingLane stagingLane = metSalesTable.StagingLaneId;
    METDoorIdentifier door;

    if (metSalesTable.InternalCrossDockOrder == NoYes::Yes &&
                metTransferTable.TransferType ==  METCrossDockTransferType::CrossDock)
    {
        stagingLane = metSalesTable.SecondaryStagingLaneId;
        door = any2Str(metSalesTable.SecondaryDoorNum);
    }
    return [door, stagingLane];
}

