/// <summary>
/// update TMS related data
/// </summary>
public void updateTMSData()
{
    super();
    //CB627_TMSEngineProcessingTOCreation
    TMSInventTransferTable  tmsTransferTable;
    TMSSalesTable           tmsSalesTable = TMSSalesTable::find(this.getSoruceId());

    tmsTransferTable.initFromInventTransferId(transferTable.TransferId);
    tmsTransferTable.setCarrierFields(this.getCarrierCode(), this.getCarriedServiceCode());
    tmsTransferTable.insert();
}

/// <summary>
