public void updatePDSQuantity(InventTransferLine _transferLine)
{
    if(salesLine.PdsCWQty)
    {
        _transferLine.PdsCWQtyTransfer = salesLine.pdsCWQtyActivateRemainder();
        _transferLine.modifiedField(fieldNum(InventTransferLine, PdsCWQtyTransfer));
    }
}

