public void CreateTransferOrder(Common _record)
{
    salesTable = _record;
    metSalesTable = METSalesTable::findByRefRecId(salesTable.RecId);
    inventParameter = InventParameters::find();

    ttsbegin;
    while select * from salesLine
        order by metSalesLine.SupplyingWarehouse
        where salesLine.SalesId == salesTable.SalesId &&
              salesLine.SalesStatus != SalesStatus::Canceled //218457 - CB238 - Bug - Liquor extraction Internal Customer not getting updated
        join * from metSalesLine where metSalesLine.SalesLine == salesLine.RecId
        && metSalesLine.OrderExtractStatus != METOrderExtractStatus::Extracted
    {
        //this.CreateTransferOrderLine(salesLine, metSalesLine, salesTable, metSalesTable);
    }

    salesTable.metUpdateExtractStatus();

    ttscommit;

    //CB627_TMSEngineProcessingTOCreation
    METTMSEngineOrderProccess::construct(METTMSEngineExecutionMode::TransferOrderCreation, transferTable).run();
}
